import type { CefrLevel, LanguageCode, LanguagePack, SentenceItem, TopicItem, VocabItem } from "@/app/lib/types";
import words from "~/content/words.json";

/**
 * All learning content in every language (generated by scripts/generate-mobile-content.mjs from content/*.csv).
 * A pack for the learner is built at runtime from a base language (the one they know) and a target language,
 * so any of the ten languages can be learned from any other. Everything stays offline.
 */

type Translations = Partial<Record<string, string>>;

interface ContentWord {
  id: string;
  difficulty: 1 | 2 | 3;
  tags: string[];
  tr: Translations;
  ex?: Translations;
}

interface ContentTopic {
  id: string;
  icon: string;
  difficulty: 1 | 2 | 3;
  titles: Translations;
  words: ContentWord[];
}

interface ContentSentence {
  id: string;
  level: string;
  tr: Translations;
  focus?: string;
}

interface ContentFile {
  version: number;
  languages: string[];
  levels: Record<string, { topics: ContentTopic[] }>;
  sentences: ContentSentence[];
}

const content = words as unknown as ContentFile;
const key = (lang: LanguageCode) => lang.toLowerCase();

const pick = (translations: Translations | undefined, lang: LanguageCode) => translations?.[key(lang)] ?? translations?.de ?? "";

/** Builds the pack "learn `target` from `base`" for one level, or null when the level has no content. */
export const buildPack = (base: LanguageCode, target: LanguageCode, level: CefrLevel): LanguagePack | null => {
  const levelContent = content.levels[level];
  if (!levelContent || base === target) return null;
  const topics: TopicItem[] = levelContent.topics.map((topic) => ({
    id: topic.id,
    title: pick(topic.titles, base),
    icon: topic.icon || undefined,
    level,
    difficulty: topic.difficulty,
    vocab: topic.words
      .map((word): VocabItem | null => {
        const de = pick(word.tr, base);
        const x = pick(word.tr, target);
        if (!de || !x) return null;
        return {
          id: word.id,
          de,
          x,
          ex: word.ex?.[key(target)] || undefined,
          exTr: word.ex?.[key(base)] || undefined,
          difficulty: word.difficulty,
          tags: word.tags.length ? word.tags : [topic.id],
        };
      })
      .filter((word): word is VocabItem => word !== null),
  }));
  const sentences: SentenceItem[] = content.sentences
    .filter((sentence) => sentence.level === level && sentence.tr[key(base)] && sentence.tr[key(target)])
    .map((sentence) => ({
      id: sentence.id,
      de: sentence.tr[key(base)] ?? "",
      x: sentence.tr[key(target)],
      translations: { [key(target)]: sentence.tr[key(target)] ?? "" },
      focusWord: sentence.focus || undefined,
    }));
  return { version: content.version, lang: target, level, topics, sentences };
};

export const hasContentFor = (level: CefrLevel) => Boolean(content.levels[level]);
